import 'package:supabase_flutter/supabase_flutter.dart';\nimport '../models/homework.dart';\nimport '../models/school_class.dart';\nimport '../models/subject.dart';\n\nclass HomeworkService {\n  final SupabaseClient _supabase;\n\n  HomeworkService(this._supabase);\n\n  // Get classes for a specific school\n  Future<List<SchoolClass>> getClasses(String schoolId) async {\n    try {\n      final response = await _supabase\n          .from('classes')\n          .select()\n          .eq('school_id', schoolId)\n          .order('order', ascending: true);\n      \n      return (response as List).map((e) => SchoolClass.fromJson(e)).toList();\n    } catch (e) {\n      throw Exception('فشل في جلب الصفوف: $e');\n    }\n  }\n\n  // Get subjects for a specific class\n  Future<List<Subject>> getSubjects(String classId) async {\n    try {\n      final response = await _supabase\n          .from('subjects')\n          .select()\n          .eq('class_id', classId);\n          \n      return (response as List).map((e) => Subject.fromJson(e)).toList();\n    } catch (e) {\n      throw Exception('فشل في جلب المواد: $e');\n    }\n  }\n\n  // Get active homework for a subject\n  Stream<List<Homework>> watchCurrentHomework(String subjectId) {\n    return _supabase\n        .from('homework')\n        .stream(primaryKey: ['id'])\n        .eq('subject_id', subjectId)\n        .eq('is_current', true)\n        .eq('is_deleted', false)\n        .map((data) => data.map((e) => Homework.fromJson(e)).toList());\n  }\n\n  // Get homework archive\n  Stream<List<Homework>> watchHomeworkArchive(String subjectId) {\n    return _supabase\n        .from('homework')\n        .stream(primaryKey: ['id'])\n        .eq('subject_id', subjectId)\n        .eq('is_current', false)\n        .eq('is_deleted', false)\n        .order('created_at', ascending: false)\n        .map((data) => data.map((e) => Homework.fromJson(e)).toList());\n  }\n\n  // Add new homework (Teacher only)\n  Future<void> addHomework(Homework newHomework) async {\n    try {\n      // First, archive current homework for this subject\n      await _supabase\n          .from('homework')\n          .update({'is_current': false})\n          .eq('subject_id', newHomework.subjectId)\n          .eq('is_current', true);\n\n      // Insert new homework\n      await _supabase.from('homework').insert(newHomework.toJson());\n    } catch (e) {\n      throw Exception('فشل في إضافة الواجب: $e');\n    }\n  }\n\n  // Soft delete homework (Teacher only)\n  Future<void> deleteHomework(String homeworkId) async {\n    try {\n      await _supabase\n          .from('homework')\n          .update({'is_deleted': true})\n          .eq('id', homeworkId);\n    } catch (e) {\n      throw Exception('فشل في حذف الواجب: $e');\n    }\n  }\n}\n